-- Find the shortest walking route through a small square-tile map.
-- grid-pathfinding: original MIT-licensed native educational port.
-- Generated by tools/ports/generate.py; edit the specification to preserve parity.
-- Input: [width, height, start_cell, goal_cell, ...row_major_grid]
-- Output: [...path_cell_ids] or [] if unreachable
-- Cell ID is y*width+x; zero tiles are walkable. BFS with equal-cost four-neighbor movement.
-- Precondition: finite, correctly shaped data; integer indices/counts/IDs.
-- See ../PORTS.md for examples, limits, and the shared test fixtures.

-- Count how many numbers are in this list.
local function port_length(a) return #a end
-- Read one number at a zero-based position; stop if that position does not exist.
local function port_get(a,i) assert(i>=0 and i==math.floor(i) and i<#a,"index"); return a[i+1] end
-- Replace a number at an existing position in the list.
local function port_put(a,i,v) port_get(a,i); a[i+1]=v end
-- Add one number to the end of the list.
local function port_push(a,v) a[#a+1]=v end
-- Round down to a whole number; minus 0.1 becomes minus 1.
local function port_floor_num(a) return math.floor(a) end

-- 1. Start on the player tile and put it in a waiting line.
-- 2. Check nearby tiles: right, left, down, and up. Skip walls and already checked tiles.
-- 3. Remember which tile led to each new tile.
-- 4. When the target is found, follow those memories backward and reverse them to get the route.
local function compute(data)
    local w = 0
    local h = 0
    local start = 0
    local goal = 0
    local n = 0
    local parent = {}
    local queue = {}
    local i = 0
    local head = 0
    local reverse = {}
    local cell = 0
    local result = {}
    local x = 0
    local y = 0
    local direction = 0
    local nx = 0
    local ny = 0
    local other = 0
    w = port_get(data, 0)
    h = port_get(data, 1)
    start = port_get(data, 2)
    goal = port_get(data, 3)
    n = (w * h)
    if ((w < 1) or (h < 1) or (start < 0) or (goal < 0) or (start >= n) or (goal >= n) or (port_length(data) ~= (n + 4))) then
        return {}
    end
    if ((port_get(data, (4 + start)) ~= 0) or (port_get(data, (4 + goal)) ~= 0)) then
        return {}
    end
    parent = {}
    queue = {start}
    i = 0
    while (i < n) do
        port_push(parent, -(1))
        i = i + 1
    end
    port_put(parent, start, start)
    head = 0
    while (head < port_length(queue)) do
        cell = port_get(queue, head)
        head = head + 1
        if (cell == goal) then
            break
        end
        x = (cell - (w * port_floor_num((cell / w))))
        y = port_floor_num((cell / w))
        direction = 0
        while (direction < 4) do
            nx = x
            ny = y
            if (direction == 0) then
                nx = nx + 1
            end
            if (direction == 1) then
                nx = nx - 1
            end
            if (direction == 2) then
                ny = ny + 1
            end
            if (direction == 3) then
                ny = ny - 1
            end
            other = ((ny * w) + nx)
            if ((nx >= 0) and (nx < w) and (ny >= 0) and (ny < h)) then
                if ((port_get(parent, other) == -(1)) and (port_get(data, (4 + other)) == 0)) then
                    port_put(parent, other, cell)
                    port_push(queue, other)
                end
            end
            direction = direction + 1
        end
    end
    if (port_get(parent, goal) == -(1)) then
        return {}
    end
    reverse = {}
    cell = goal
    while (cell ~= start) do
        port_push(reverse, cell)
        cell = port_get(parent, cell)
    end
    port_push(reverse, start)
    result = {}
    i = (port_length(reverse) - 1)
    while (i >= 0) do
        port_push(result, port_get(reverse, i))
        i = i - 1
    end
    return result
end
return {compute=compute}
